INSERT INTO stories (slug, title_english, title_chinese, audio_url, image_url, tags, hsk_level, story_url, chinese_text, pinyin_text, content_html)
VALUES ('i-have-been-learning-chinese-for-three-years', 'I have been learning Chinese for three years', '我学汉语三年了', 'https://traffic.libsyn.com/secure/learnchinese/3150.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/3150-qos0q9te7dfq5xvpx5ggjlawl4elv5xd1a2h2onbyq.jpg', '', 'HSK3', 'https://mandarinbean.com/i-have-been-learning-chinese-for-three-years/', '大龙今天急死我了苏南怎么了大龙我在学校门口遇到一位老奶奶她问路我听不懂苏南怎么会听不懂大龙她一开始说的是方言后来才说普通话但是她普通话的口音很重我还是不明白苏南难怪你听不懂后来呢大龙多亏了吴小咪她刚好到学校门口顺便帮了那位老奶奶苏南那太好了不过中国有这么多方言连很多中国人都听不懂更不要说外国人了你听不懂也没关系别难过了大龙我学汉语四年了越学越觉得难苏南我学汉语三年了虽然汉语有点难但是我越学越喜欢大龙和英语相比汉字非常特别我上高中的时候认识了一位中国朋友他给我介绍了中国的文化和汉字从那个时候起我开始对汉语感兴趣所以我在高中和大学都选修了汉语和中国文化课但是那个时候我身边的中国人很少学汉语的人也不多我没有很好的语言环境口语和听力比阅读和语法差得多因此我计划一毕业就来中国继续学习苏南原来你是这样开始学汉语的大龙你呢苏南我小时候跟爸爸来中国旅行吃过很多中国的美食就爱上了中国菜后来我想学做更多的中国菜品尝更多的中国美食所以就来中国学习了大龙既然这样我们就多认识一些中国朋友好好练习我们的汉语吧', 'Dàlóng jīn tiān jí sǐ wǒ le Sūnán zěn me le Dàlóng wǒ zài xué xiào mén kǒu yù dào yī wèi lǎo nǎinai tā wèn lù wǒ tīng bù dǒng Sūnán zěn me huì tīng bù dǒng Dàlóng tā yī kāi shǐ shuō de shì fāng yán hòu lái cái shuō pǔ tōng huà dàn shì tā pǔ tōng huà de kǒu yīn hěn zhòng wǒ hái shì bù míng bái Sūnán nán guài nǐ tīng bù dǒng hòu lái ne Dàlóng duō kuī le Wú Xiǎomī tā gāng hǎo dào xué xiào mén kǒu shùn biàn bāng le nà wèi lǎo nǎinai Sūnán nà tài hǎo le bù guò zhōng guó yǒu zhè me duō fāng yán lián hěn duō zhōng guó rén dōu tīng bù dǒng gèng bù yào shuō wài guó rén le nǐ tīng bù dǒng yě méi guān xì bié nán guò le Dàlóng wǒ xué hàn yǔ sì nián le yuè xué yuè jué de nán Sūnán wǒ xué hàn yǔ sān nián le suī rán hàn yǔ yǒu diǎn nán dàn shì wǒ yuè xué yuè xǐ huān Dàlóng hé yīng yǔ xiāng bǐ hàn zì fēi cháng tè bié wǒ shàng gāo zhōng de shí hòu rèn shí le yī wèi zhōng guó péng yǒu tā gěi wǒ jiè shào le zhōng guó de wén huà hé hàn zì cóng nà gè shí hòu qǐ wǒ kāi shǐ duì hàn yǔ gǎn xìng qù suǒ yǐ wǒ zài gāo zhōng hé dà xué dōu xuǎn xiū le hàn yǔ hé zhōng guó wén huà kè dàn shì nà gè shí hòu wǒ shēn biān de zhōng guó rén hěn shǎo xué hàn yǔ de rén yě bù duō wǒ méi yǒu hěn hǎo de yǔ yán huán jìng kǒu yǔ hé tīng lì bǐ yuè dú hé yǔ fǎ chà de duō yīn cǐ wǒ jì huà yī bì yè jiù lái zhōng guó jì xù xué xí Sūnán yuán lái nǐ shì zhè yàng kāi shǐ xué hàn yǔ de Dàlóng nǐ ne Sūnán wǒ xiǎo shí hòu gēn bà bà lái zhōng guó lǚ xíng chī guò hěn duō zhōng guó de měi shí jiù ài shàng le zhōng guó cài hòu lái wǒ xiǎng xué zuò gèng duō de zhōng guó cài pǐn cháng gèng duō de zhōng guó měi shí suǒ yǐ jiù lái zhōng guó xué xí le Dàlóng jì rán zhè yàng wǒ men jiù duō rèn shí yī xiē zhōng guó péng yǒu hǎo hǎo liàn xí wǒ men de hàn yǔ ba', '<div class="elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content" data-element_type="widget" data-id="4064e155" data-widget_type="theme-post-content.default">
