INSERT INTO stories (slug, title_english, title_chinese, audio_url, image_url, tags, hsk_level, story_url, chinese_text, pinyin_text, content_html)
VALUES ('modern-social-classes', 'Modern social classes', '现代社会阶层', 'https://traffic.libsyn.com/secure/learnchinese/6131.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/6131-qu9sqpyo2st2fy4mj2q180p4j9jgr0c8hpjd7briaa.jpg', '', 'HSK6', 'https://mandarinbean.com/modern-social-classes/', '由于社会分工的形成不同的人群被划分到不同的阶层领阶层就是一种普遍的说法它反映了个人的社会地位以及在生产过程中所承担的职责白领指的是管理人员介于资本家和普通工人之间也被称为高级打工人一些著名大公司中有一些超级高薪的打工人年薪远超一般富人被称为打工皇帝普通的工人被称为蓝领主要从事体力劳动在工厂的生产线上工作随着生产自动化水平的提高钢领出现了开始取代传统的工人成为生产中的重要角色这也直接带来了两个结果一是劳动生产力水平提高二是大量出现的失业人员推动了第三产业服务业的扩大在服务业中出现了以女性为主的粉领阶层粉领是第三产业的主要力量在服务行业中具有重要地位信息社会正在改变我们的社会结构形成新的社会阶层与电视电脑和互联网一同成长的世代代表了信息时代的新人类由于世纪是一个完全信息化的时代世代将成为世纪的金领阶层', 'yóu yú shè huì fēn gōng de xíng chéng bù tóng de rén qún bèi huà fēn dào bù tóng de jiē céng lǐng jiē céng jiù shì yī zhǒng pǔ biàn de shuō fǎ tā fǎn yìng le gè rén de shè huì dì wèi yǐ jí zài shēng chǎn guò chéng zhōng suǒ chéng dān de zhí zé bái lǐng zhǐ de shì guǎn lǐ rén yuán jiè yú zī běn jiā hé pǔ tōng gōng rén zhī jiān yě bèi chēng wéi gāo jí dǎ gōng rén yī xiē zhù míng dà gōng sī zhōng yǒu yī xiē chāo jí gāo xīn de dǎ gōng rén nián xīn yuǎn chāo yī bān fù rén bèi chēng wéi dǎ gōng huáng dì pǔ tōng de gōng rén bèi chēng wéi lán lǐng zhǔ yào cóng shì tǐ lì láo dòng zài gōng chǎng de shēng chǎn xiàn shàng gōng zuò suí zhe shēng chǎn zì dòng huà shuǐ píng de tí gāo gāng lǐng chū xiàn le kāi shǐ qǔ dài chuán tǒng de gōng rén chéng wéi shēng chǎn zhōng de zhòng yào jué sè zhè yě zhí jiē dài lái le liǎng gè jié guǒ yī shì láo dòng shēng chǎn lì shuǐ píng tí gāo èr shì dà liàng chū xiàn de shī yè rén yuán tuī dòng le dì sān chǎn yè fú wù yè de kuò dà zài fú wù yè zhōng chū xiàn le yǐ nǚ xìng wéi zhǔ de fěn lǐng jiē céng fěn lǐng shì dì sān chǎn yè de zhǔ yào lì liàng zài fú wù háng yè zhōng jù yǒu zhòng yào dì wèi xìn xī shè huì zhèng zài gǎi biàn wǒ men de shè huì jié gòu xíng chéng xīn de shè huì jiē céng yǔ diàn shì diàn nǎo hé hù lián wǎng yī tóng chéng zhǎng de shì dài dài biǎo le xìn xī shí dài de xīn rén lèi yóu yú shì jì shì yī gè wán quán xìn xī huà de shí dài shì dài jiāng chéng wéi shì jì de jīn lǐng jiē céng', '<div class="elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content" data-element_type="widget" data-id="4064e155" data-widget_type="theme-post-content.default">
